import { getSeoMeta } from '@shopify/hydrogen';

export const meta = ({ data }) => {
  return getSeoMeta({
    title: data.product.title,
    description: data.product.description,
    titleTemplate: '%s | Minha Loja',
  });
};

query ProductSeo($handle: String!) {
  product(handle: $handle) {
    title
    description
    seo {
      title
      description
    }
  }
}

export const meta = ({ data, location }) => {
  const canonicalUrl = `https://minha-loja.com${location.pathname}`;
  return [
    ...getSeoMeta({ title: data.product.title }),
    { tagName: 'link', rel: 'canonical', href: canonicalUrl },
  ];
};

export const meta = ({ data }) => {
  return [
    ...getSeoMeta({ title: data.product.title }),
    {
      'script:ld+json': {
        '@context': 'https://schema.org',
        '@type': 'Product',
        name: data.product.title,
        description: data.product.description,
        offers: {
          '@type': 'Offer',
          price: data.product.selectedVariant.price.amount,
          priceCurrency: data.product.selectedVariant.price.currencyCode,
        },
      },
    },
  ];
};

query ProductRoute($handle: String!) {
  product(handle: $handle) {
    title
    seo { title description }
    selectedVariant { price { amount currencyCode } }
  }
}
